insert into public.villages (id, name, epithet, description, condition, services, restoration, map_x, map_y, updated_at) values ('kingsfall', 'Kingsfall', 'Seat of the Crown', 'The walled capital on the Downs, home to the Royal Council and the Old Archive. Beneath the Downs lies the barrow where the war against Kirmada ended — or was thought to.', 'strained', '{"communications":"degraded","roads":"operational","water":"operational","food":"operational","wards":"degraded"}'::jsonb, 64, 49, 51, now() - interval '360 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('kingsfall', 'City wards reinforced at the north gate. Archive closed to the public.', 'Steward Ilsabet Crane', 58, now() - interval '2880 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('kingsfall', 'Black-flame lantern contained beneath the Archive. East stacks remain sealed.', 'Steward Ilsabet Crane', 64, now() - interval '360 minutes');
insert into public.villages (id, name, epithet, description, condition, services, restoration, map_x, map_y, updated_at) values ('ashenreach', 'Ashenreach', 'The Ember Terraces', 'A terraced market town on the western trade road. Its kilns have burned for three hundred years; since the curse, the ash no longer settles.', 'afflicted', '{"communications":"degraded","roads":"disrupted","water":"operational","food":"degraded","wards":"operational"}'::jsonb, 38, 18, 44, now() - interval '1680 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('ashenreach', 'Western trade road closed at the second milestone. Carts are being turned back.', 'Steward Corin Ashby', 30, now() - interval '2880 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('ashenreach', 'Foot detour through Blackbriar opened. Food carts rerouted via the south lane.', 'Steward Corin Ashby', 38, now() - interval '1680 minutes');
insert into public.villages (id, name, epithet, description, condition, services, restoration, map_x, map_y, updated_at) values ('hollowmere', 'Hollowmere', 'Village of the Still Lake', 'Fishers and well-keepers on the shore of a lake so still it holds the stars by day. The water turned black on the night of the first tolling.', 'afflicted', '{"communications":"operational","roads":"operational","water":"disrupted","food":"degraded","wards":"degraded"}'::jsonb, 52, 34, 70, now() - interval '180 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('hollowmere', 'Lake intake sealed. Water is being carried in from Kingsfall cisterns.', 'Steward Wenna Hollis', 20, now() - interval '5760 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('hollowmere', 'Filter beds rebuilt. Boiled water is safe to drink; the purification rite is next.', 'Steward Wenna Hollis', 52, now() - interval '180 minutes');
insert into public.villages (id, name, epithet, description, condition, services, restoration, map_x, map_y, updated_at) values ('thornwatch', 'Thornwatch', 'Fortress of the Northern Ridge', 'A border keep and its village, guardians of the ward-line that has held the northern dark at bay since the Accord. Most of the stones have gone cold.', 'critical', '{"communications":"degraded","roads":"degraded","water":"operational","food":"operational","wards":"disrupted"}'::jsonb, 21, 47, 15, now() - interval '1200 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('thornwatch', 'Ward-line failure confirmed along the ridge. Families below the keep are moving inside the walls.', 'Steward Bram Holloway', 8, now() - interval '4320 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('thornwatch', 'Survey complete. Recovered codex pages give us the binding words; re-inscription begins at dawn.', 'Steward Bram Holloway', 21, now() - interval '1200 minutes');
insert into public.villages (id, name, epithet, description, condition, services, restoration, map_x, map_y, updated_at) values ('moonfall', 'Moonfall', 'The Bell-Tower Cliffs', 'A cliff-top village of bell-ringers and beacon-keepers that relays the kingdom''s signals to the eastern coast. The beacons went dark; the bells did not stop.', 'afflicted', '{"communications":"disrupted","roads":"operational","water":"operational","food":"operational","wards":"degraded"}'::jsonb, 30, 80, 32, now() - interval '1560 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('moonfall', 'All seven beacons extinguished. Messages east now travel by rider — expect a day''s delay.', 'Steward Osric Penhale', 30, now() - interval '1560 minutes');
insert into public.villages (id, name, epithet, description, condition, services, restoration, map_x, map_y, updated_at) values ('blackbriar', 'Blackbriar', 'Hamlet Beneath the Briarwood', 'Farmsteads and granaries at the edge of the old forest, feeding half the western villages. The grey mould has been burned out; the harvest is thin but clean.', 'strained', '{"communications":"operational","roads":"degraded","water":"operational","food":"degraded","wards":"operational"}'::jsonb, 78, 24, 24, now() - interval '4320 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('blackbriar', 'Granary cleared and resupplied from Greyhaven. Ration lines have ended.', 'Steward Ada Fenwick', 78, now() - interval '4320 minutes');
insert into public.villages (id, name, epithet, description, condition, services, restoration, map_x, map_y, updated_at) values ('greyhaven', 'Greyhaven', 'The Harbour of Lamps', 'The kingdom''s southern harbour, so far spared the worst of the curse. Its ships now carry grain and lamp-oil to the afflicted villages.', 'stable', '{"communications":"operational","roads":"operational","water":"operational","food":"operational","wards":"operational"}'::jsonb, 96, 68, 80, now() - interval '7200 minutes');
insert into public.village_updates (village_id, message, author_name, restoration, created_at) values ('greyhaven', 'Fog horn repaired. Harbour fully operational and supplying relief convoys.', 'Steward Lio Marsh', 96, now() - interval '7200 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0031', 'KNG-' || to_char(now(), 'YYYY') || '-0031', 'Lake water turned black and perfectly still', 'At the third bell after midnight the whole of Hollowmere lake went black, like poured ink. It does not ripple when stones are thrown in. Fish are floating at the shore and the well-houses draw the same black water. Two households have fallen ill after drinking before the warning.', 'water_food', 'critical', 'hollowmere', 'Lake intake below the Fisher''s Steps', 'in_restoration', false, 'Maud Teller', 'Waterkeepers of Hollowmere', now() - interval '7200 minutes', now() - interval '180 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0031', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '7200 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0031', 'status', 'Verified on site. Waterkeepers dispatched; do not draw lake water.', 'Steward Wenna Hollis', 'steward', 'submitted', 'acknowledged', now() - interval '7080 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0031', 'status', 'Intake sealed. Divers are searching the lake bed for the source.', 'Steward Wenna Hollis', 'steward', 'acknowledged', 'in_restoration', now() - interval '5760 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0031', 'note', 'A drowned bell was raised from the lake bed and silenced. Water at the intake is running clear for the first time in four days.', 'Steward Wenna Hollis', 'steward', null, null, now() - interval '1440 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0031', 'note', 'Filter beds rebuilt. Boil all drawn water until the purification rite is complete.', 'Steward Wenna Hollis', 'steward', null, null, now() - interval '180 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0032', 'KNG-' || to_char(now(), 'YYYY') || '-0032', 'Northern ward-stones dark along the ridge', 'The ward-stones on the ridge path above Thornwatch have stopped glowing — I counted more than twenty dark between the keep and the old watchtower. Frost is forming on the inside of the line, and something large was heard moving below the scree last night.', 'wards', 'critical', 'thornwatch', 'Ridge path between the keep and the Old Watchtower', 'in_restoration', false, 'Sergeant Edda Marr', 'Wardwright Company III', now() - interval '4320 minutes', now() - interval '1200 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0032', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '4320 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0032', 'status', 'Ward-line failure confirmed. Wardwright Company III riding north tonight.', 'Steward Bram Holloway', 'steward', 'submitted', 'acknowledged', now() - interval '4290 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0032', 'status', 'Wardwrights on the ridge. Families below the keep are sheltering inside the walls.', 'Steward Bram Holloway', 'steward', 'acknowledged', 'in_restoration', now() - interval '3600 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0032', 'note', 'Survey complete: 24 of 31 stones are dark. Recovered pages of the Thornbound Codex confirm the binding words needed to re-inscribe them.', 'Steward Bram Holloway', 'steward', null, null, now() - interval '1200 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0033', 'KNG-' || to_char(now(), 'YYYY') || '-0033', 'Western trade road swallowed by an ash fissure', 'A fissure has opened across the trade road two miles west of Ashenreach. It breathes warm ash and the edge keeps crumbling. A cart and two oxen went in; the driver escaped. Merchants are now trying to cross at night, which is dangerous.', 'roads', 'high', 'ashenreach', 'Western trade road, second milestone', 'acknowledged', false, 'Tobin Reyes, carter', 'Roadwardens of the West', now() - interval '3240 minutes', now() - interval '1680 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0033', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '3240 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0033', 'status', 'Road closed at the second milestone. Roadwardens posted at both ends.', 'Steward Corin Ashby', 'steward', 'submitted', 'acknowledged', now() - interval '2880 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0033', 'note', 'Fissure mapped at 140 paces. A foot detour through Blackbriar is open; no carts.', 'Steward Corin Ashby', 'steward', null, null, now() - interval '1680 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0034', 'KNG-' || to_char(now(), 'YYYY') || '-0034', 'Signal beacons extinguished; bells ring at midnight', 'All seven beacons on the Moonfall cliffs went out at once and will not relight — the oil burns, but gives no light. Every night at midnight the bell-tower rings thirteen times, though the tower is locked and empty.', 'communication', 'high', 'moonfall', 'Beacon line and the Old Bell-Tower', 'acknowledged', true, null, 'Signal Corps of Moonfall', now() - interval '1920 minutes', now() - interval '1560 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0034', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '1920 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0034', 'status', 'Signal Corps assigned. Messages east are travelling by rider until the beacons return.', 'Steward Osric Penhale', 'steward', 'submitted', 'acknowledged', now() - interval '1560 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0035', 'KNG-' || to_char(now(), 'YYYY') || '-0035', 'Granary stores blighted with grey mould', 'The east granary is covered in a grey mould that spreads overnight. It smells of wet ash. About a third of the winter grain is ruined and families are beginning to ration.', 'water_food', 'moderate', 'blackbriar', 'East granary, Miller''s Lane', 'resolved', false, 'Ada Fenwick', 'Granary Wardens', now() - interval '12960 minutes', now() - interval '4320 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0035', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '12960 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0035', 'status', 'Granary Wardens assigned. Do not eat from the east granary.', 'Steward Ada Fenwick', 'steward', 'submitted', 'acknowledged', now() - interval '12900 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0035', 'status', 'Blighted stores being burned beyond the hedge line.', 'Steward Ada Fenwick', 'steward', 'acknowledged', 'in_restoration', now() - interval '11520 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0035', 'status', 'Granary cleared and scrubbed with salt. Clean grain delivered from Greyhaven; rationing has ended.', 'Steward Ada Fenwick', 'steward', 'in_restoration', 'resolved', now() - interval '4320 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0036', 'KNG-' || to_char(now(), 'YYYY') || '-0036', 'Lantern found burning with black flame in the Old Archive', 'An archivist found a lantern on a reading desk in the east stacks, burning with a flame that gives off darkness instead of light. The candles nearest it went out and would not relight. No one admits to having brought it in.', 'cursed_artifact', 'high', 'kingsfall', 'Old Archive, east stacks', 'in_restoration', false, 'Archivist Pell', 'Royal Arcanum', now() - interval '840 minutes', now() - interval '360 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0036', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '840 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0036', 'status', 'Royal Arcanum notified. East stacks evacuated.', 'Steward Ilsabet Crane', 'steward', 'submitted', 'acknowledged', now() - interval '780 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0036', 'status', 'Arcanists are working to contain the object.', 'Steward Ilsabet Crane', 'steward', 'acknowledged', 'in_restoration', now() - interval '660 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0036', 'note', 'The lantern is sealed in a lead casket beneath the Archive. Do not approach the east stacks.', 'Steward Ilsabet Crane', 'steward', null, null, now() - interval '360 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0037', 'KNG-' || to_char(now(), 'YYYY') || '-0037', 'Shelter needs dry bedding and healers', 'The chapel hall is sheltering fourteen families whose wells went black. We are out of dry bedding and several children have the grey cough. We need a healer and blankets before the frost.', 'shelter_healing', 'moderate', 'hollowmere', 'Chapel hall, Lantern Square', 'acknowledged', false, 'Sister Agnes', 'Healers of the Grey Order', now() - interval '1440 minutes', now() - interval '1200 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0037', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '1440 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0037', 'status', 'Two healers and a cart of blankets leaving Kingsfall at first light.', 'Steward Wenna Hollis', 'steward', 'submitted', 'acknowledged', now() - interval '1200 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0038', 'KNG-' || to_char(now(), 'YYYY') || '-0038', 'Shadows moving against the wind on the terraces', 'On the upper kiln terraces, the shadows of the chimneys lean towards the east no matter where the sun is. Tonight they started to move while nothing else did. No one has been hurt, but the children are frightened.', 'magical_anomaly', 'low', 'ashenreach', 'Upper kiln terraces', 'submitted', true, null, null, now() - interval '300 minutes', now() - interval '300 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0038', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '300 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0039', 'KNG-' || to_char(now(), 'YYYY') || '-0039', 'Messenger ravens refusing to fly south', 'None of the keep''s ravens will carry messages south toward Kingsfall. They circle the tower and return. Our reports to the Council are now going by rider, which takes two days.', 'communication', 'moderate', 'thornwatch', 'Raven loft, Thornwatch Keep', 'submitted', false, 'Hob the Loftkeeper', null, now() - interval '130 minutes', now() - interval '130 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0039', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '130 minutes');
insert into public.incidents (id, reference, title, description, category, severity, village_id, location, status, anonymous, reporter_name, assigned_team, submitted_at, updated_at) values ('inc-0040', 'KNG-' || to_char(now(), 'YYYY') || '-0040', 'Harbour fog horn sounding unprompted', 'The harbour fog horn has been sounding on clear nights with no one at the lever. Fishermen worry it is a warning of something coming in from the sea.', 'communication', 'low', 'greyhaven', 'Harbour mouth, the Lamp Mole', 'resolved', false, 'Jory Penn', 'Kingsfall City Watch', now() - interval '8640 minutes', now() - interval '7200 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0040', 'submitted', 'Report received by the Royal Dispatch.', 'The Royal Dispatch', 'system', null, null, now() - interval '8640 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0040', 'status', 'Watch engineer sent to inspect the horn mechanism.', 'Steward Lio Marsh', 'steward', 'submitted', 'acknowledged', now() - interval '8520 minutes');
insert into public.incident_updates (incident_id, kind, message, author_name, author_role, from_status, to_status, created_at) values ('inc-0040', 'status', 'The horn''s valve was jammed open by salt crust. Cleaned and tested. No enchantment found.', 'Steward Lio Marsh', 'steward', 'acknowledged', 'resolved', now() - interval '7200 minutes');
insert into public.announcements (id, title, summary, body, priority, category, village_id, issued_by, published_at, state) values ('dsp-council-artifact', 'The Council investigates a newly discovered cursed artifact', 'A lantern burning with black flame was found in the Old Archive. It is contained. Report any object that behaves the same way.', 'Last night an archivist found a lantern in the east stacks of the Old Archive that burns with a flame of darkness. It has been sealed in lead beneath the Archive by the Royal Arcanum, and the east stacks are closed until further notice.
insert into public.announcements (id, title, summary, body, priority, category, village_id, issued_by, published_at, state) values ('dsp-alliance-relays', 'The Alliance Protocol is invoked: allied relays carry the Crown''s word', 'With the Moonfall beacons dark, KAPIDHWAJ''s signal relays now link every village to the Royal Dispatch.', 'By decree of the Royal Council, the old accord with KAPIDHWAJ — the allied order of ward engineers and signal keepers — has been invoked.
insert into public.announcements (id, title, summary, body, priority, category, village_id, issued_by, published_at, state) values ('dsp-thornwatch-barrier', 'Protective barrier has failed near Thornwatch', 'Most of the northern ward-stones are dark. Travel on the ridge path is forbidden; families below the keep should shelter inside the walls.', 'The ward-line on the northern ridge has failed along most of its length. Wardwright Company III is re-inscribing the stones, beginning in the east.
insert into public.announcements (id, title, summary, body, priority, category, village_id, issued_by, published_at, state) values ('dsp-hollowmere-water', 'Water restoration has begun in Hollowmere', 'The lake intake is sealed and the filter beds are rebuilt. Boiled water is now safe; the purification rite follows.', 'The source of the black water — a drowned bell on the lake bed — has been raised and silenced by the Waterkeepers.
insert into public.announcements (id, title, summary, body, priority, category, village_id, issued_by, published_at, state) values ('dsp-western-road', 'Western trade road temporarily closed beyond Ashenreach', 'An ash fissure has opened at the second milestone. Carts must turn back; a foot detour runs through Blackbriar.', 'The western trade road is closed at the second milestone west of Ashenreach, where a fissure of warm ash has opened across the road.
insert into public.announcements (id, title, summary, body, priority, category, village_id, issued_by, published_at, state) values ('dsp-lantern-curfew', 'Keep one light burning after dusk', 'Every household is asked to keep a single lamp lit through the night until the curse is lifted.', 'By order of the Council, every household in the kingdom is asked to keep a single lamp burning from dusk until dawn.
insert into public.announcements (id, title, summary, body, priority, category, village_id, issued_by, published_at, state) values ('dsp-moonfall-refuge', 'Moonfall bell-tower open as refuge', 'Superseded: the bell-tower is now locked after the midnight ringing began.', 'The Old Bell-Tower in Moonfall was opened as a night refuge on the first day of the curse.
insert into public.initiatives (id, title, summary, village_id, lead, incident_ids, next_steps) values ('init-northern-wards', 'Re-binding the Northern Wards', 'Re-inscribing the thirty-one ward-stones of the Thornwatch ridge with the binding words recovered from the Thornbound Codex.', 'thornwatch', 'Wardwright Company III', array['inc-0032', 'inc-0039']::text[], array['Re-inscription of the eastern stones begins at dawn.', 'Ridge path stays closed until the vigil is complete.']::text[]);
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-nw-1', 'init-northern-wards', 'Survey every ward-stone on the ridge', 0, true, now() - interval '1200 minutes');
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-nw-2', 'init-northern-wards', 'Recover the binding words from the Codex', 1, true, now() - interval '1080 minutes');
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-nw-3', 'init-northern-wards', 'Re-inscribe the twelve eastern stones', 2, false, null);
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-nw-4', 'init-northern-wards', 'Re-inscribe the nineteen western stones', 3, false, null);
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-nw-5', 'init-northern-wards', 'Hold the vigil of confirmation', 4, false, null);
insert into public.initiative_updates (initiative_id, message, author_name, created_at) values ('init-northern-wards', 'Binding words confirmed against three surviving pages. Ink and chisels issued.', 'Steward Bram Holloway', now() - interval '1080 minutes');
insert into public.initiatives (id, title, summary, village_id, lead, incident_ids, next_steps) values ('init-hollowmere-waters', 'Clearing the Hollowmere Waters', 'Removing the source of the black water and restoring safe drinking water to every well-house.', 'hollowmere', 'Waterkeepers of Hollowmere', array['inc-0031', 'inc-0037']::text[], array['Purification rite at the next new moon.', 'Well-houses reopen one by one after testing.']::text[]);
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-hw-1', 'init-hollowmere-waters', 'Seal the lake intake', 0, true, now() - interval '5760 minutes');
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-hw-2', 'init-hollowmere-waters', 'Raise the drowned bell', 1, true, now() - interval '1440 minutes');
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-hw-3', 'init-hollowmere-waters', 'Rebuild the filter beds', 2, true, now() - interval '180 minutes');
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-hw-4', 'init-hollowmere-waters', 'Perform the purification rite', 3, false, null);
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-hw-5', 'init-hollowmere-waters', 'Reopen all well-houses', 4, false, null);
