insert into public.initiatives (id, title, summary, village_id, lead, incident_ids, next_steps) values ('init-western-road', 'Reopening the Western Trade Road', 'Bridging the ash fissure at the second milestone so carts can reach the western villages again.', 'ashenreach', 'Roadwardens of the West', array['inc-0033']::text[], array['Ironwood beams arriving from Blackbriar.', 'Night crossings remain forbidden.']::text[]);
