insert into public.initiatives (id, title, summary, village_id, lead, incident_ids, next_steps) values ('init-moonfall-beacons', 'Rekindling the Moonfall Beacons', 'Restoring the eastern signal line and silencing the midnight bells.', 'moonfall', 'Signal Corps of Moonfall', array['inc-0034']::text[], array['Arcanists to examine the bell-tower before anyone enters it.', 'Messages east travel on the allied relay until the beacons are relit.']::text[]);
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-mb-0', 'init-moonfall-beacons', 'Raise an Alliance Protocol relay on the cliffs', 0, true, now() - interval '1500 minutes');
