insert into public.initiatives (id, title, summary, village_id, lead, incident_ids, next_steps) values ('init-blackbriar-granary', 'Blackbriar Granary Recovery', 'Clearing the grey mould and resupplying the western villages'' winter grain.', 'blackbriar', 'Granary Wardens', array['inc-0035']::text[], array['Monthly inspection of all granaries until spring.']::text[]);
insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-bg-1', 'init-blackbriar-granary', 'Burn the blighted stores', 0, true, now() - interval '11520 minutes');
