insert into public.initiative_milestones (id, initiative_id, title, position, done, done_at) values ('ms-bg-3', 'init-blackbriar-granary', 'Resupply from Greyhaven', 2, true, now() - interval '4320 minutes');
insert into public.initiative_updates (initiative_id, message, author_name, created_at) values ('init-blackbriar-granary', 'Clean grain delivered. Rationing ended across Blackbriar.', 'Steward Ada Fenwick', now() - interval '4320 minutes');
insert into public.artifacts (id, name, epithet, glyph, origin, description, lore, disaster, containment, village_id, incident_ids) values ('lantern-of-unlit-hours', 'The Lantern of Unlit Hours', 'It burns, and the room grows darker.', 'lantern', 'Found in the Old Archive, Kingsfall', 'A tarnished iron lantern whose flame casts darkness instead of light. Nearby candles gutter and refuse to relight.', 'Kirmada is said to have carried it through the siege of Kingsfall so that no sentry would see him pass. Where it burns, the night forgets to end.', 'Its twin flame is believed to be smothering the Moonfall beacons.', 'Sealed in lead beneath the Archive', 'kingsfall', array['inc-0036', 'inc-0034']::text[]);
insert into public.artifacts (id, name, epithet, glyph, origin, description, lore, disaster, containment, village_id, incident_ids) values ('thornbound-codex', 'The Thornbound Codex', 'Its pages were once the wards themselves.', 'codex', 'Pages scattered along the Thornwatch ridge', 'A book bound in briar, whose pages hold the binding words that wake the ward-stones. Kirmada tore it apart; its pages drift on the ridge wind.', 'Each page Kirmada tore loose put out a stone on the northern line. Each page recovered lets a wardwright light one again.', 'Its unbinding caused the failure of the northern ward-line.', 'Fragments recovered — three pages', 'thornwatch', array['inc-0032']::text[]);
insert into public.artifacts (id, name, epithet, glyph, origin, description, lore, disaster, containment, village_id, incident_ids) values ('drowned-bell', 'The Drowned Bell', 'It tolled once, under the water.', 'bell', 'Raised from the bed of Hollowmere lake', 'A small bronze bell, green with age, its clapper bound with black hair. When it rang beneath the lake, the water turned to ink.', 'The fishers say Kirmada drowned it there as a promise: that one day every bell in the kingdom would ring for him.', 'Its tolling poisoned the Hollowmere waters.', 'Raised and silenced by the Waterkeepers', 'hollowmere', array['inc-0031']::text[]);
insert into public.artifacts (id, name, epithet, glyph, origin, description, lore, disaster, containment, village_id, incident_ids) values ('ashen-compass', 'The Ashen Compass', 'It does not point north.', 'compass', 'Last seen on the Ashenreach terraces', 'A brass compass filled with grey ash instead of a needle. The ash gathers and points, always, toward the same place under Kingsfall Downs.', 'Travellers who follow it never arrive where they meant to go. The road it opens is a wound, and the earth splits to make way for it.', 'Linked to the ash fissure on the western trade road and the leaning shadows of the terraces.', 'Unaccounted for', 'ashenreach', array['inc-0033', 'inc-0038']::text[]);
insert into public.artifacts (id, name, epithet, glyph, origin, description, lore, disaster, containment, village_id, incident_ids) values ('sleepers-hourglass', 'The Sleeper''s Hourglass', 'The sand runs upward.', 'hourglass', 'Beneath Kingsfall Downs, in the Sleeper''s barrow', 'An hourglass of black glass buried with the one the Crown believed it had defeated. Its sand falls upward, and very little of it remains below.', 'Kirmada did not die at the Battle of Kingsfall Downs. He slept, and set a glass to wake him. The Council''s scryers read the remaining sand at thirteen minutes and four seconds.', 'The source of the curse clock that every steward now watches.', 'Running', 'kingsfall', '{}'::text[]);
